package com.luminor.tavernquest.di
import com.luminor.tavernquest.data.local.database.*;import com.luminor.tavernquest.data.local.database.dao.*;import com.luminor.tavernquest.data.local.preferences.SettingsDataSource;import com.luminor.tavernquest.data.repository.*;import com.luminor.tavernquest.domain.repository.*;import dagger.Module;import dagger.Provides;import dagger.hilt.InstallIn;import dagger.hilt.components.SingletonComponent;import javax.inject.Singleton
@Module @InstallIn(SingletonComponent::class) object RepositoryModule{@Provides @Singleton fun heroRepo(d:HeroDao):HeroRepository=HeroRepositoryImpl(d);@Provides @Singleton fun tavernRepo(db:TavernQuestDatabase):TavernRepository=TavernRepositoryImpl(db);@Provides @Singleton fun contractRepo(t:ContractTemplateDao,d:DailyContractDao):ContractRepository=ContractRepositoryImpl(t,d);@Provides @Singleton fun questRepo(db:TavernQuestDatabase,ids:com.luminor.tavernquest.core.util.UuidProvider):QuestRepository=QuestRepositoryImpl(db,ids);@Provides @Singleton fun journalRepo(d:QuestCompletionDao):JournalRepository=JournalRepositoryImpl(d);@Provides @Singleton fun xpRepo(d:XpLedgerDao):XpRepository=XpRepositoryImpl(d);@Provides @Singleton fun settingsRepo(d:SettingsDataSource):SettingsRepository=SettingsRepositoryImpl(d)}
